class Solution:
    def maximumSumScore(self, nums: List[int]) -> int:
        n = len(nums)
        best = float('-inf')
        for i in range(n):
            front = sum(nums[:i + 1])
            back = sum(nums[i:])
            best = max(best, front, back)
        return best

