class Solution {
public:
    long long maximumSumScore(vector<int>& nums) {
        int n = nums.size();
        long long best = LLONG_MIN;
        for (int i = 0; i < n; i++) {
            long long front = 0, back = 0;
            for (int j = 0; j <= i; j++) front += nums[j];
            for (int j = i; j < n; j++) back += nums[j];
            best = max(best, max(front, back));
        }
        return best;
    }
};

